old:
if !compilation.diagnostics.is_empty() {
    ui.separator();
    ui.collapsing("Diagnostics", |ui| {
        for diagnostic in compilation.diagnostics {
            ui.label(format!("{}: {}", diagnostic.code, diagnostic.message));
        }
    });
}

new:
